-- EN / HOME
('en', 'home', 'service-depth', 'Automotive locksmith coverage', 'Complete mobile automotive locksmith support', 'Use this section to explain the main service categories customers can request, including lockouts, replacement keys, key fobs, transponder programming, broken key extraction, and ignition-related help.', '["Service details are managed from Services admin", "Use published services to control the cards", "Keep descriptions clear for Google Ads and customer trust"]'::jsonb, 'View services', '/en/services', 10, true),
('en', 'home', 'customer-info', 'Before requesting service', 'Information customers should prepare', 'Use this section to explain what customers should send before service: vehicle make, model, year, location, urgency, key situation, and contact phone number.', '["Vehicle make, model, and year", "Exact location or nearby landmark", "Whether all keys are lost", "Phone number for confirmation"]'::jsonb, 'Request service', '/en/contact#request-service', 20, true),
('en', 'home', 'area-section', 'Local coverage', 'Mobile service areas', 'Use this section to explain your coverage area and how mobile automotive locksmith requests are handled across Philadelphia and nearby locations.', '["Coverage depends on technician availability", "Response time depends on location and urgency", "Use area pages for local SEO and customer clarity"]'::jsonb, 'View areas', '/en/areas', 30, true),

