('en', 'service-detail', 'hero', 'Automotive locksmith service', '', 'This service page explains what the customer can request, what details are needed, and what factors may affect availability, pricing, and timing.', '[]'::jsonb, 'Call now', 'tel:+12155550100', 10, true),
('en', 'service-detail', 'overview', 'Service overview', 'What this service includes', 'Use this block for general service-page explanation. The specific service title, intro, excerpt, and SEO fields still come from Services admin.', '[]'::jsonb, null, null, 20, true),
('en', 'service-detail', 'readiness', null, 'Information customers should prepare', 'Ask customers to provide vehicle make, model, year, current location, phone number, urgency, and whether all keys are lost.', '["Vehicle make, model, and year", "Exact location", "Current key situation", "Phone number for confirmation"]'::jsonb, null, null, 30, true),
('en', 'service-detail', 'pricing', null, 'What affects price and timing', 'Final price and service time may depend on vehicle security system, key type, parts availability, programming requirements, distance, time of day, and job complexity.', '["Vehicle security system", "Key or fob type", "Parts availability", "Programming requirements", "Distance and timing"]'::jsonb, null, null, 40, true),
('en', 'service-detail', 'authorization', null, 'Authorization and safety', 'Customers may need to confirm authorization to access or service the vehicle before work begins.', '["Proof of ownership or authorization may be requested", "Details are confirmed before service", "Safety and fraud prevention matter"]'::jsonb, null, null, 50, true),
('en', 'service-detail', 'process', 'How the request works', 'Service request process', 'Use this block to explain the customer journey from request to confirmation.', '["Submit service and vehicle details", "Confirm location, urgency, and phone number", "Review availability, parts, and programming needs", "Confirm next step before service begins"]'::jsonb, null, null, 60, true),

