('en', 'area-detail', 'hero', 'Local automotive locksmith coverage', '', 'This area page explains mobile automotive locksmith availability, common requests, and customer preparation for this service area.', '[]'::jsonb, 'Call now', 'tel:+12155550100', 10, true),
('en', 'area-detail', 'overview', 'Area overview', 'Mobile coverage information', 'Use this block for general area-page explanation. The specific city, title, intro, supported services, and SEO fields still come from Areas admin.', '[]'::jsonb, null, null, 20, true),
('en', 'area-detail', 'prep', null, 'What to prepare before service', 'Customers should prepare vehicle details and location information before requesting mobile service.', '["Vehicle make, model, and year", "Exact address or landmark", "Whether all keys are lost", "Whether the vehicle is locked, running, or in a garage", "Phone number for fast confirmation"]'::jsonb, null, null, 30, true),
('en', 'area-detail', 'supported-services', null, 'Services commonly requested here', 'Use this block to explain the common automotive locksmith services requested in local coverage pages.', '["Car lockout help", "Replacement car keys", "Key fob and transponder programming", "Broken key extraction", "Ignition-related support"]'::jsonb, null, null, 40, true),
('en', 'area-detail', 'local-info', null, 'Local service information', 'Use this block to explain how service availability works locally.', '["Mobile service depends on technician availability and location", "Response times may vary by traffic, distance, weather, and urgency", "Final price depends on vehicle details, parts, and job complexity"]'::jsonb, null, null, 50, true),
