('es', 'area-detail', 'prep', null, 'Qué preparar antes del servicio', 'El cliente debe preparar datos del vehículo y ubicación antes de solicitar servicio móvil.', '["Marca, modelo y año", "Dirección exacta o referencia", "Si perdió todas las llaves", "Si el auto está cerrado, encendido o en garaje", "Teléfono para confirmación"]'::jsonb, null, null, 30, true),
