('ru', 'service-detail', 'hero', 'Автомобильная услуга', '', 'Эта страница объясняет, что клиент может запросить, какие данные нужны и что влияет на доступность, цену и сроки.', '[]'::jsonb, 'Позвонить', 'tel:+12155550100', 10, true),
('ru', 'service-detail', 'overview', 'Описание услуги', 'Что включает услуга', 'Используйте этот блок для общего описания. Конкретные title, intro, excerpt и SEO идут из Services admin.', '[]'::jsonb, null, null, 20, true),
('ru', 'service-detail', 'readiness', null, 'Что клиенту подготовить', 'Попросите марку, модель, год, текущую локацию, телефон, срочность и информацию о том, потеряны ли все ключи.', '["Марка, модель и год", "Точная локация", "Ситуация с ключом", "Телефон для подтверждения"]'::jsonb, null, null, 30, true),
('ru', 'service-detail', 'pricing', null, 'Что влияет на цену и сроки', 'Финальная цена и время могут зависеть от системы безопасности авто, типа ключа, наличия деталей, программирования, расстояния, времени и сложности.', '["Система безопасности авто", "Тип ключа или брелка", "Наличие деталей", "Необходимость программирования", "Расстояние и время"]'::jsonb, null, null, 40, true),
('ru', 'service-detail', 'authorization', null, 'Авторизация и безопасность', 'Клиенту может потребоваться подтвердить право доступа или обслуживания автомобиля до начала работы.', '["Может потребоваться подтверждение права", "Детали подтверждаются до начала", "Безопасность и защита от мошенничества важны"]'::jsonb, null, null, 50, true),
('ru', 'service-detail', 'process', 'Как проходит заявка', 'Процесс заявки', 'Объясните путь клиента от заявки до подтверждения.', '["Отправить услугу и данные авто", "Подтвердить локацию, срочность и телефон", "Проверить доступность, детали и программирование", "Подтвердить следующий шаг до начала услуги"]'::jsonb, null, null, 60, true),

