('ru', 'area-detail', 'supported-services', null, 'Частые услуги здесь', 'Объясните частые услуги на локальных страницах.', '["Открытие авто", "Замена ключей", "Программирование брелков и transponder", "Извлечение сломанного ключа", "Помощь с зажиганием"]'::jsonb, null, null, 40, true),
('ru', 'area-detail', 'local-info', null, 'Локальная информация', 'Объясните, как работает локальная доступность.', '["Мобильный сервис зависит от доступности и локации", "Сроки зависят от трафика, расстояния, погоды и срочности", "Цена зависит от автомобиля, деталей и сложности"]'::jsonb, null, null, 50, true),
('ru', 'area-detail', 'coverage-notes', null, 'Заметки по покрытию', 'Уточните ограничения покрытия и ожидания клиента.', '["Покрытие может меняться по времени и доступности", "Некоторые авто требуют специальные детали или инструменты", "Детали подтверждаются до начала услуги"]'::jsonb, null, null, 60, true)
